    "keyNotes": "• Land as an Agricultural Resource: Free gift of nature; immobile, non-reproducible; subject to the law of diminishing returns.\n• Land Uses:\n  - Agricultural: Crop production, livestock grazing/pasture, fish farming, agroforestry.\n  - Non-Agricultural: Residential housing, road networks, mining, industrial parks.\n• Land Tenure Systems in Ghana:\n  - Communal Land Tenure: Land owned collectively by the entire community; all members have usufructuary rights to farm. Problems: Cannot be used as bank collateral; leads to land fragmentation.\n  - Stool / Skin Lands: Custodianship vested in traditional chiefs or earth priests (Tindana) on behalf of ancestors, living, and unborn generations.\n  - Individual / Freehold Tenure: Absolute private ownership through purchase or inheritance; easily pledged as bank collateral.\n  - Leasehold Tenure: Right to occupy land for a specified duration (e.g. 50 or 99 years) on payment of rent.\n  - Traditional Sharecropping Systems:\n    * Abusa System: Agricultural proceeds divided into three equal parts (1/3 to landowner, 2/3 to tenant farmer who bore development costs).\n    * Abunu System: Proceeds divided equally into two parts (common in newly established cocoa farms where landlord funded initial inputs).",
