    "keyNotes": "• Agricultural Ecology: The study of the interactions between crops, farm animals, and their surrounding environmental factors.\n• Environmental Factors Affecting Agriculture:\n  1. Climatic Factors:\n     - Rainfall: Primary source of water for rainfed agriculture in Ghana; determines planting seasons (bimodal in the south, unimodal in the north).\n     - Temperature: Influences transpiration, seed germination, photosynthetic enzyme activity, and heat stress in livestock.\n     - Sunlight (Photoperiodism): Solar radiation drives photosynthesis; duration of light regulates flowering in short-day vs. long-day plants.\n     - Wind: Facilitates cross-pollination, but high winds cause lodging of cereals, coastal erosion, and excessive evaporation during Harmattan.\n  2. Biotic Factors:\n     - Beneficial: Honeybees (pollination), nitrogen-fixing bacteria (Rhizobium), earthworms (soil aeration and casting).\n     - Harmful: Weed competitors, fungal pathogens, insect pests (armyworms, stem borers), parasitic worms, and disease vectors (tsetse fly).\n  3. Edaphic Factors: Soil pH, texture, structure, organic matter content, and drainage.",
