    "title": "Rocks & Soil Formation",
    "description": "Rock types (igneous, sedimentary, metamorphic), weathering agents (physical, chemical, biological), and soil profile layers (horizons O, A, B, C, R).",
    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Rocks as Parent Materials: Rocks are the mineral foundations of soil. Weathering of granite yields coarse sandy soils, while basalt weathering produces fertile clayey soils.\n• Agents of Soil Weathering:\n  - Physical / Mechanical Weathering: Temperature fluctuations (exfoliation), running water, wind abrasion, and frost action cracking rocks.\n  - Chemical Weathering: Chemical alteration of mineral composition via:\n    * Carbonation: Carbonic acid (rainwater + CO2) dissolving calcium carbonate in limestone.\n    * Oxidation: Oxygen reacting with ferrous iron minerals to form weak, crumbly rust (iron oxides).\n    * Hydration and Hydrolysis.\n  - Biological Weathering: Penetration of tree roots into crevices, burrowing rodents, lichen acids, and human quarrying.\n• The Soil Profile: A vertical section through the soil revealing horizontal layers called HORIZONS:\n  - O-Horizon: Organic layer (undecomposed leaf litter and dark humus).\n  - A-Horizon (Topsoil): Zone of maximum biological activity and high mineral fertility; critical for shallow crop roots.\n  - B-Horizon (Subsoil): Zone of illuviation where minerals, clay, and iron oxides leach down and accumulate.\n  - C-Horizon: Partially weathered parent rock material.\n  - R-Horizon: Unweathered solid bedrock.",
