    "keyNotes": "• Essential Plant Nutrients:\n  - Macro-Nutrients (required in large quantities):\n    * Nitrogen (N): Promotes vegetative green growth, leafy development, and chlorophyll synthesis. Deficiency: General chlorosis (yellowing of older leaves) and stunted growth.\n    * Phosphorus (P): Promotes root development, early flowering, and fruit/seed formation. Deficiency: Purple or reddish pigmentation on leaves and poor root system.\n    * Potassium (K): Regulates stomatal opening, enzyme activation, and disease resistance. Deficiency: Marginal leaf chlorosis and scorching (burnt leaf tips).\n    * Calcium (Ca), Magnesium (Mg: central atom of chlorophyll), Sulfur (S).\n  - Micro-Nutrients (trace elements): Iron, Boron, Zinc, Manganese, Copper, Molybdenum, Chlorine.\n• Organic Manures vs. Inorganic Fertilizers:\n  - Organic Manures: Farmyard manure, compost, green manure. Adds humus, improves soil structure, increases water retention, slow-release; bulky, variable nutrient content.\n  - Inorganic (Chemical) Fertilizers: Straight (Urea, Sulfate of Ammonia) vs. Compound (NPK 15-15-15). Highly concentrated, rapid response; risk of soil acidification and water pollution if overused.",
