    "description": "Forms of soil water (gravitational, capillary, hygroscopic), field capacity, wilting point, irrigation systems (drip, sprinkler, furrow), and drainage.",
    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Forms of Soil Water:\n  - Gravitational Water: Excess water that drains freely downward through large soil pores under the pull of gravity. Unusable by plants; leaches nutrients.\n  - Capillary Water: Water held in micropores by surface tension against the force of gravity. The PRIMARY source of water absorbed by crop roots!\n  - Hygroscopic Water: Thin film of water molecules held tightly on the surface of soil colloids by molecular attraction; unavailable to plant roots.\n• Water Constants:\n  - Field Capacity (FC): Maximum amount of water retained by soil after excess gravitational water has drained away (usually 2–3 days after heavy rain).\n  - Permanent Wilting Point (PWP): Soil moisture level at which plant roots can no longer extract water, causing permanent wilting and death.\n• Irrigation Methods:\n  - Surface / Flood Irrigation (furrow, basin): Low cost, but high water loss through evaporation and percolation.\n  - Overhead / Sprinkler Irrigation: Simulates rainfall; suitable for undulating terrain; high capital cost.\n  - Drip / Trickle Irrigation: Water delivered directly to the root zone through perforated pipes; highest water use efficiency (> 90%); prevents fungal leaf splash.",
