      "objectives": [
        "Distinguish between gravitational, capillary, and hygroscopic water in soil",
        "Calculate available water capacity between Field Capacity and Permanent Wilting Point",
        "Compare the operational efficiency of drip, sprinkler, and furrow irrigation systems in Ghana"
      ],
