    "keyNotes": "• Simple Hand Tools:\n  - Cutlass / Machete: Clearing bushes, weeding, cutting crops, harvesting.\n  - Hoe (West African hoe): Making mounds, ridges, weeding, harvesting tubers.\n  - Garden Fork & Hand Trowel: Transplanting nursery seedlings, loosening nursery beds.\n  - Secateurs & Shears: Pruning cocoa branches, trimming hedges, harvesting fruits.\n  - Knapsack Sprayer: Applying herbicides, insecticides, and foliar fertilizers.\n• Tractor-Mounted Farm Machinery:\n  - Primary Tillage Implements:\n    * Disc Plough: Consists of heavy concave steel discs; cuts, lifts, and inverts furrow slices; best for stony, stumpy tropical soils.\n    * Mouldboard Plough: Inverts complete soil slices; suitable for stone-free, weed-free temperate soils.\n  - Secondary Tillage Implements:\n    * Disc Harrow: Pulverizes large clods left by ploughs into a fine tilth for seedbeds.\n    * Ridger: Forms raised planting ridges or furrows for root and tuber crops.\n• Maintenance Practices: Washing after use, greasing moving joints, sharpening cutting blades, storing in dry tool sheds.",
