    "keyNotes": "• Farm Surveying Defined: The measurement of dimensional relationships (distances, directions, angles, elevations) on a farm to determine boundaries and map terrain.\n• Surveying Instruments & Uses:\n  - Gunter's Chain / Measuring Tape: Measuring linear horizontal distances (Chain = 66 feet or 100 links).\n  - Ranging Poles: Wooden or metal poles painted alternating red and white; used for marking straight sightlines over distance.\n  - Arrows (Survey Pins): Metal pins used for marking chain lengths completed on the ground.\n  - Prismatic Compass: Measuring magnetic bearings and directional angles.\n  - Abney Level / Clinometer: Measuring slopes and gradients for contour terracing.\n• Principles of Farmstead Planning:\n  - Farmstead: The operational core of a farm containing farmhouse, animal pens, silos, tool sheds, and processing units.\n  - Layout Rules:\n    * Farmhouse placed on high, well-drained ground upwind of animal pens (prevents bad odors and disease).\n    * Livestock pens situated downwind and downslope from domestic quarters.\n    * Storage silos located near farm access roads for easy vehicular loading.",
