    "description": "Principles of agricultural economics (diminishing returns, opportunity cost), farm records and accounts, balance sheet, and farm budgeting.",
    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Economic Principles in Farm Management:\n  - Law of Diminishing Returns: Adding extra fertilizer units to fixed land eventually yields smaller increments in harvest.\n  - Opportunity Cost: Real cost of choosing one farm enterprise over another (e.g. planting maize instead of soybeans).\n• Importance of Farm Records:\n  - Evaluates profitability, aids farm planning, secures bank agricultural loans, determines tax liabilities.\n• Types of Farm Records & Accounts:\n  - Farm Inventory Record: Comprehensive list of all farm assets (land, machinery, livestock, feed) with monetary values at a given date.\n  - Production / Yield Records: Daily milk yields, egg collection sheets, crop tonnage harvested.\n  - Cash Book / Financial Receipts and Payments.\n  - Farm Balance Sheet: Net Worth (Equity) = Total Farm Assets - Total Farm Liabilities.\n  - Profit and Loss Account: Computes Net Farm Income = Total Farm Receipts + Closing Inventory - (Total Farm Expenses + Opening Inventory).",
