    "keyNotes": "• Agricultural Extension Defined: An informal out-of-school educational process that communicates proven scientific agricultural research findings and modern innovations to farmers to improve productivity and rural living standards.\n• Extension Teaching Methods:\n  - Individual Contact Methods: Farm visits, office calls, telephone consultations. Highly effective, builds deep trust; very time-consuming and expensive.\n  - Group Contact Methods: Method demonstrations (showing HOW to plant hybrid seeds), result demonstrations (showing YIELD differences), farmer field schools, workshops.\n  - Mass Media Methods: Radio agricultural programs, television documentaries, posters, mobile SMS advisories. Reaches thousands instantly; lacks personal interaction.\n• Innovation-Adoption Stages (Rogers):\n  1. Awareness -> 2. Interest -> 3. Evaluation -> 4. Trial -> 5. Adoption.\n  - Adopter Categories: Innovators (first 2.5%), Early Adopters, Early Majority, Late Majority, Laggards.\n• Key Institutions in Ghana: Ministry of Food and Agriculture (MOFA), CSIR (Crops Research Institute, Animal Research Institute), CRIG (Cocoa Research Institute of Ghana).",
