    "isFreeTrial": true,
    "isVip": false,
    "keyNotes": "• Site Selection Criteria: Soil fertility (well-drained loam), gentle slope to prevent erosion, proximity to water source, accessible farm road.\n• Land Preparation Steps:\n  1. Land clearing and destumping.\n  2. Primary Tillage (Ploughing): Cutting and inverting soil to bury weeds and improve aeration.\n  3. Secondary Tillage (Harrowing): Breaking soil clods into fine tilth.\n  4. Ridging / Mounding: Essential for tuber crops (yam, sweet potato) to facilitate tuber expansion.\n• Planting Principles:\n  - Seed Viability Testing: Floatation test or Petri dish germination percentage test: (Seeds Germinated / Total Seeds Tested) * 100. Should exceed 85%.\n  - Planting Methods: Direct seeding (drilling, dibbling, broadcasting) vs. Transplanting from nursery.\n  - Spacing & Plant Population: Correct spacing optimizes sunlight and soil nutrient interception while reducing weed competition:\n    * Plant Population = (Field Area in m2) / (Plant Spacing: Inter-row m * Intra-row m).\n  - Thinning (removing excess weak seedlings) and Supplying / Vacancy filling (replacing failed seeds).",
