    "id": "shs-crp-topic-04",
    "subjectId": "crop-husbandry",
    "level": "SHS 1",
    "term": 1,
    "orderIndex": 4,
    "title": "Husbandry of Cereal Crops: Maize & Rice",
    "description": "Agronomic requirements, improved varieties, land preparation, planting, fertilizer regimes, weed control, harvesting, and storage.",
    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Maize Husbandry (Zea mays):\n  - Environmental Requirements: 600–1,200 mm rainfall, well-drained loamy soil rich in organic matter, pH 5.8–7.0.\n  - Improved Varieties in Ghana: Obatanpa (Quality Protein Maize - QPM), Omankwa, Abontem.\n  - Planting: 2 seeds per hole at 75 cm x 25 cm (thin to 1 plant per stand at 2 weeks).\n  - Fertilizer: Basal NPK 15-15-15 at planting or 2 weeks; top-dress with Urea at 4–6 weeks during knee-high stage.\n  - Pests & Diseases: Fall armyworm (Spodoptera frugiperda), stem borers, maize streak virus, rust.\n  - Harvesting: When silk turns dark brown and moisture drops below 15%; dry to 12% moisture for crib/silo storage.\n• Rice Husbandry (Oryza sativa):\n  - Lowland / Swamp rice vs. Upland rice. Improved varieties: Jasmine 85, Agra rice.\n  - Nursery brooding and transplanting seedlings at 21 days at 20 cm x 20 cm spacing.\n  - Water management (bunding), harvesting at physiological maturity, threshing, parboiling, and milling.",
