      "objectives": [
        "Describe the agronomic practices for cultivating Quality Protein Maize (Obatanpa) in Ghana",
        "Formulate integrated fertilizer and pest management programs for cereal crops",
        "Explain the post-harvest operations of harvesting, shelling, drying, and hermetic storage"
      ],
