    "keyNotes": "• Cocoa Husbandry (Theobroma cacao):\n  - Climate & Soil: Rainforest belt, 1,200–1,500 mm rainfall, deep fertile clay-loam soils, protection from direct sun.\n  - Nursery: Raised beds in perforated polythene bags under shade; transplant seedlings at 6 months at 3 m x 3 m spacing.\n  - Shade Management: Requires nurse shade trees (Plantain, Gliricidia) in early years; permanent shade thinned later.\n  - Major Pests & Diseases:\n    * Mirids / Capsids (Distantiella theobroma): Sucks sap from young shoots and pods; controlled by spraying with approved insecticides (e.g. Confidor).\n    * Black Pod Disease (Phytophthora palmivora): Fungal rot turning pods black; controlled by removing infected pods, improving canopy aeration, and spraying copper-based fungicides.\n    * Cocoa Swollen Shoot Virus (CSSVD): Spread by mealybugs; eradicated ONLY by cutting down infected trees (supported by COCOBOD compensation).\n  - Post-Harvest: Fermentation under banana/plantain leaves for 6 days (develops chocolate flavor) followed by sun-drying on raised wooden mats.\n• Oil Palm Husbandry (Elaeis guineensis):\n  - Varieties: Dura (thick shell), Pisifera (shell-less), Tenera (hybrid: thin shell, thick mesocarp, highest oil yield).",
