    "keyNotes": "• Vegetable Nursery Management:\n  - Seeds are tiny and vulnerable; raised on raised nursery beds protected by palm frond shade.\n  - Pricking Out: Transferring overcrowded young seedlings into separate nursery containers or wider nursery spacing to encourage stocky growth.\n  - Hardening Off: Gradually reducing shade and watering 1–2 weeks before field transplanting to accustom seedlings to harsh field sunlight.\n• Tomato Husbandry (Solanum lycopersicum):\n  - Transplanting: Done late afternoon or on a cloudy day to minimize transplanting shock. Spacing: 60 cm x 45 cm.\n  - Staking: Supporting plants with wooden stakes prevents fruit contact with damp soil, reducing fruit rot and facilitating spraying.\n  - Physiological Disorder: Blossom-End Rot: Black sunken leathery rot on the fruit base caused by CALCIUM DEFICIENCY compounded by irregular watering.\n• Pepper Husbandry (Capsicum spp.):\n  - Hot peppers (Scotch Bonnet, Bird's eye) and Sweet bell peppers.\n  - Pest: Aphids transmitting pepper veinal mottle virus, fruit borers.",
