    "keyNotes": "• Animal Husbandry Defined: The agricultural branch concerned with the breeding, feeding, housing, healthcare, and management of domestic farm animals.\n• Economic Importance in Ghana:\n  - High-Quality Animal Protein: Meat, milk, eggs containing essential amino acids critical for child cognitive development.\n  - Farm Power: Draught bullocks for ploughing and cart haulage in northern savanna zones.\n  - Organic Fertilizer: Manure enriches soil fertility and biogas production.\n  - By-products: Leather, hides, horns, feathers, bone meal for industrial manufacturing.\n  - Financial Security: \"Walking bank accounts\" liquidated during school fee seasons or medical emergencies.\n• Anatomical & Dietary Classification:\n  - Ruminants (Polygastric / Cud-chewing): Four-chambered stomach; ferment fibrous cellulose grasses (Cattle, Sheep, Goats).\n  - Non-Ruminants / Monogastrics: Single simple stomach; require digestible concentrate feeds (Pigs, Rabbits).\n  - Poultry: Domesticated avian birds (Chickens, Turkeys, Ducks, Guinea fowls).\n  - Micro-Livestock: Small-bodied domestic animals (Grasscutters, Snails, Rabbits, Honeybees).",
