    "keyNotes": "• The Ruminant Stomach (Cattle, Sheep, Goats):\n  1. Rumen (Paunch): Largest compartment; vast microbial fermentation vat containing billions of anaerobic bacteria, protozoa, and fungi that break down cellulose into volatile fatty acids (VFAs).\n  2. Reticulum (Honeycomb): Traps heavy foreign metal objects; assists in regurgitating the food bolus back to the mouth for rumination (chewing the cud).\n  3. Omasum (Manyplies / Bible): Contains leaf-like folds that absorb water and residual VFAs from ingested digesta.\n  4. Abomasum (True Stomach): Secretes gastric juices (hydrochloric acid, pepsin) for enzymatic chemical digestion, identical to a monogastric stomach!\n• Avian (Poultry) Digestive Anatomy:\n  - Beak -> Esophagus -> Crop (temporary storage and softening of food) -> Proventriculus (glandular stomach secreting enzymes) -> Gizzard (muscular grinding stomach containing swallowed grit/small stones) -> Small intestine -> Caeca -> Cloaca / Vent.",
