    "keyNotes": "• Principles of Animal Breeding: Improving genetic merit of future livestock generations for economic traits (milk yield, growth rate, egg production, disease resistance).\n• Selection Methods:\n  - Individual / Mass Selection: Animals chosen based solely on their own personal physical performance and phenotypic traits.\n  - Pedigree Selection: Selection based on ancestors' performance recorded in pedigree records.\n  - Progeny Testing: Evaluating a sire's genetic worth by measuring the average performance of his offspring (critical for evaluating dairy bulls).\n• Breeding Systems:\n  - Inbreeding: Mating of closely related animals (brother-sister, sire-daughter). Increases homozygosity, fixes desirable traits; risk of inbreeding depression (low vitality, deformities).\n  - Outbreeding / Outcrossing: Mating of unrelated animals within the same breed.\n  - Crossbreeding: Mating animals of two different pure breeds (e.g. Holstein-Friesian bull x N'Dama cow). Explores HETEROSIS / HYBRID VIGOR (offspring perform better than parent average).\n• Artificial Insemination (AI): Collecting semen from superior progeny-tested sires, diluting, cryopreserving in liquid nitrogen (-196°C), and depositing into female reproductive tract during estrus.",
