    "keyNotes": "• Cattle Breeds in Ghana:\n  - N'Dama: Humpless, brown, indigenous to Fouta Djallon; renowned for genetic TRYPANOTOLERANCE (resists tsetse fly sleeping sickness); good beef conformation.\n  - West African Shorthorn (WASH): Small, humpless, hardy, trypanotolerant; native to coastal and forest margins of Ghana.\n  - Zebu / White Fulani / Sokoto Gudali: Humped cattle with long horns; high meat and milk yields; susceptible to trypanosomiasis, restricted to northern savanna and Accra plains.\n• Management Practices:\n  - Colostrum Feeding: Calves must ingest maternal colostrum within first 6–12 hours of life to absorb life-saving maternal antibodies.\n  - Castration (Burdizzo or elastrator): Done on male bull calves not destined for breeding to promote docility and fattening.\n  - Dehorning / Disbudding: Removing horn buds to prevent injuries among stock.\n  - Grazing Systems: Extensive pastoral nomadism (Fulani transhumance), semi-intensive paddock grazing, intensive feedlot beef fattening.",
