    "title": "Management of Small Ruminants: Sheep & Goat Production",
    "description": "Breeds (West African Dwarf - WAD, Sahelian), housing, flushing, steaming up, lambing/kidding management, castration, and PPR control.",
    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Small Ruminants in Ghana:\n  - West African Dwarf (WAD) Sheep and Goats: Compact, short-legged, highly prolific, disease-hardy, trypanotolerant; well-adapted to humid forest zones.\n  - Sahelian / Djallonké Long-Legged Breeds: Tall, high carcass weight; found in dry northern savannahs.\n• Reproductive Management:\n  - Flushing: Increasing the energy and protein plane of nutrition of ewes/does 2–3 weeks before mating to boost ovulation rate and multiple births (twins/triplets).\n  - Steaming Up: Feeding pregnant ewes/does high-quality concentrates during the final 4–6 weeks of gestation to nourish rapidly growing fetuses and build udder colostrum reserves.\n• Routine Management & Health:\n  - Hoof trimming (prevents foot rot in wet muddy kraals).\n  - Peste des Petits Ruminants (PPR / Goat Plague): Highly contagious viral disease causing fever, mouth sores, diarrhea, and high mortality; prevented by annual PPR vaccination.\n  - Internal Parasite Control: Strategic deworming against liver flukes and roundworms.",
