    "keyNotes": "• Brooding Management (0–4 Weeks of Age):\n  - Preparing the Brooder: Disinfecting house, spreading dry wood shavings litter (5–8 cm), testing hover heaters/heat lamps 24 hours before chick arrival.\n  - Temperature: Maintain 32–35°C in week 1, reducing by 2.5°C weekly until room temperature.\n  - Chick Behavior as Thermometer: If chicks crowd under heater = too cold; if panting against walls = too hot; if evenly dispersed = ideal temperature!\n  - Offer anti-stress electrolytes and chick starter mash (20–22% CP).\n• Broiler Production (Meat Birds):\n  - Reared for 6–8 weeks to reach 1.8–2.2 kg liveweight using high-energy broiler starter and finisher feeds.\n• Layer Production (Table Eggs):\n  - Reared from pullets; commence laying around 18–20 weeks of age, peaking at 90–95% production.\n  - Culling Non-Layers: Identifying unproductive hens: dull shrunken comb, dry tight vent, yellow pigmentation in legs/beak (good layers have bleached white shanks, wide moist vent!).\n  - Egg Candling: Inspecting eggs over light to detect cracks, blood spots, and fertile embryo development.\n• Biosecurity: Strict vaccination schedule against Marek's, Gumboro (IBD), and Newcastle Disease.",
