    "keyNotes": "• Non-Traditional Animal Production: Farming indigenous non-conventional species to diversify farmer income, conserve wildlife, and supply organic bushmeat delicacies.\n• Grasscutter Domestication (Thryonomys swinderianus):\n  - Highly prized bushmeat in Ghana.\n  - Housing: Two-tiered concrete cages or pens with mesh doors.\n  - Feeding: Elephant grass, Guinea grass, sugarcane, cassava peelings, maize grain supplements.\n  - Breeding: 1 male to 4–6 females (colony); gestation 152–156 days; produces precocial young (born fully furred with open eyes).\n• Snail Farming (Heliciculture):\n  - Species: Giant African Snail (Achatina achatina, Archachatina marginata).\n  - Environment: High humidity, moist loamy soil rich in calcium for shell formation, cool shaded wooden boxes or trench pens.\n  - Nutrition: Pawpaw leaves, cabbage, watermelon rind, calcium carbonate supplement.\n  - Hermaphroditic: Possesses both male and female organs, but cross-fertilization is required.\n• Beekeeping (Apiculture): Top-bar hives (Kenya Top Bar Hive), honey harvesting, beeswax processing.",
