    "keyNotes": "• Signs of Animal Health vs. Sickness:\n  - Healthy: Bright alert eyes, moist cool muzzle (in cattle), smooth glossy coat, active appetite, normal chewing of cud, normal body temperature and respiration.\n  - Diseased: Dull sunken eyes, dry muzzle, rough ruffled coat, anorexia (refusal to feed), cessation of rumination, discharge from orifices, abnormal feces.\n• Major Livestock Diseases:\n  - Bacterial: Anthrax (Bacillus anthracis: zoonotic spore-forming bacteria; carcass must NOT be opened! Bloated bleeding from orifices); Brucellosis (contagious abortion); Tuberculosis.\n  - Viral: Newcastle Disease (poultry: twisting of neck, green diarrhea); African Swine Fever; Foot and Mouth Disease (FMD); Gumboro.\n  - Protozoan: Trypanosomiasis (transmitted by tsetse fly Glossina); Coccidiosis (bloody diarrhea in poultry; controlled by coccidiostats).\n• Parasites:\n  - Ectoparasites: Ticks (transmit redwater and heartwater; controlled by chemical acaricide dipping/spraying), lice, mites.\n  - Endoparasites: Tapeworms, roundworms, liver flukes (Fasciola hepatica: uses mud snail as intermediate host; causes liver rot).",
