    "keyNotes": "• Types of Pastures:\n  - Natural Pasture (Rangeland): Native uncultivated grasslands (common in guinea and Sudan savannas). Low productivity during dry season.\n  - Established / Artificial Pasture: Sown deliberately with certified, high-yielding, palatable forage grasses and legumes.\n• Forage Species in West Africa:\n  - Grasses (Poaceae): Guinea grass (Panicum maximum), Elephant / Napier grass (Pennisetum purpureum), Northern gamba grass (Andropogon gayanus).\n  - Legumes (Fabaceae): Centrosema pubescens (Centro), Stylosanthes guianensis (Stylo), Pueraria phaseoloides (Kudzu), Leucaena leucocephala (browse tree).\n• Carrying Capacity & Stocking Rate:\n  - Carrying Capacity: The maximum number of animal units a specific pasture area can support sustainably without vegetation degradation over a year.\n  - Overgrazing: Stocking rate exceeds carrying capacity; results in destruction of palatable grass, soil compaction, and severe erosion.\n• Range Management Techniques: Rotational grazing (dividing pasture into paddocks), controlled burning to remove moribund lignified grass, weed control, and reseeding.",
