    "keyNotes": "• Site Selection Criteria for Earthen Ponds:\n  - Topography: Gently sloping terrain (1–2% slope) allows gravity filling and complete gravity drainage without expensive pumping.\n  - Soil Characteristics: Clay or sandy-clay loam soil is mandatory; must contain at least 20–35% clay to prevent seepage. Squeeze ball test: moist soil squeezed into a ball that does not crumble is suitable.\n  - Water Supply: Reliable, unpolluted water year-round (streams, rivers, springs, boreholes).\n• Critical Water Quality Parameters:\n  - Dissolved Oxygen (DO): Most critical parameter! Optimal: 5.0–8.0 mg/L (ppm). Below 3.0 mg/L causes stress; below 1.0 mg/L causes mass asphyxiation.\n  - Water Temperature: Optimal for tropical fish: 26°C to 30°C. Cold water slows digestion and growth.\n  - Water pH: Optimal: 6.5 to 8.5. pH < 6.0 is acidic (stunts growth); pH > 9.5 is toxic.\n  - Total Ammonia Nitrogen (TAN): Un-ionized ammonia (NH3) is highly toxic; should remain < 0.05 mg/L.\n  - Transparency / Turbidity: Measured using a Secchi Disc; optimal visibility: 30–40 cm.",
