    "keyNotes": "• Nutritional Requirements of Fish:\n  - High Protein Demand: Fry need 45–50% Crude Protein; fingerlings need 35–40%; grow-out fish need 30–35%. Fish require 10 essential amino acids.\n  - Lipids (energy and omega-3 fatty acids), carbohydrates (digestible starch for pellet binding), vitamins, and minerals.\n• Feed Types:\n  - Natural Food: Phytoplankton (microscopic algae) and Zooplankton (rotifers, daphnia) stimulated by pond fertilization.\n  - Formulated Commercial Feeds:\n    * Floating (Extruded) Pellets: Expanded under high heat and steam; float on surface allowing farmers to observe feeding vigor and avoid over-feeding. Preferred for tilapia and catfish!\n    * Sinking Pellets: Sinks to bottom; cheaper, but risk of water pollution if unconsumed.\n• Feed Conversion Ratio (FCR):\n  - FCR = (Total Weight of Feed Fed) / (Total Live Weight Gained by Fish).\n  - An FCR of 1.2 to 1.5 is excellent (means 1.2–1.5 kg of feed produces 1.0 kg of fresh fish). Lower FCR = higher feeding efficiency!",
