    "keyNotes": "• Spectrum of Aquaculture Systems:\n  - Extensive System: Low stocking density (< 1 fish/m2); relies solely on natural plankton food produced by sunlight; no artificial feeding; low yield (500–1,500 kg/ha/yr).\n  - Semi-Intensive System: Moderate stocking (2–5 fish/m2); pond fertilization plus supplementary feeding with agro-byproducts (wheat bran, brewery waste); yields 3,000–8,000 kg/ha/yr.\n  - Intensive System: High stocking density (> 10–50 fish/m2); complete reliance on nutritionally balanced commercial floating feeds; active aeration.\n• Modern Specialized Systems:\n  - Cage Aquaculture (Volta Lake): Net enclosures suspended in large natural water bodies by floating pontoons; excellent water exchange by lake currents; high yields (e.g. 5–10 tons per cage).\n  - Recirculating Aquaculture Systems (RAS): Water continuously recycled through mechanical filters (removing solids) and biological biofilters (nitrifying bacteria converting toxic ammonia to harmless nitrates). Low water consumption, biosecure, but high capital cost.",
