    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Fish Harvesting Operations:\n  - Partial / Selective Harvesting: Using drag seine nets with specific mesh sizes to crop out marketable-sized fish while leaving smaller fish to grow.\n  - Complete / Total Harvesting: Draining the pond completely into the harvesting sump or monk basin to collect all stock.\n  - Pre-Harvest Conditioning: Starve fish for 24–48 hours prior to harvest! Clears stomach contents, minimizes water fouling, prevents meat contamination, and reduces transport stress.\n• Post-Harvest Handling & Preservation:\n  - Fish Spoilage: Fish spoil rapidly within 12 hours at tropical temperatures due to bacterial action, autolytic enzyme breakdown, and fat oxidation.\n  - Cold Preservation: Storing in crushed ice (1:1 fish to ice ratio) in insulated containers.\n  - Fish Smoking (Dominant in Ghana):\n    * Traditional round mud ovens vs. The Chorkor Smoker (developed by FAO and Food Research Institute in Chorkor, Accra).\n    * Chorkor Smoker Benefits: Uses stacked wooden trays over a rectangular clay combustion chamber; smokes 5 times more fish with 60% less firewood; produces uniform, golden, high-quality smoked fish with low polycyclic aromatic hydrocarbons (PAH).\n  - Salting and Sun-Drying: Preparing fermented salt fish (\"Momoni\" / \"Koobi\").",
