    "keyNotes": "• Ecological Forest Classification of Ghana:\n  1. High Forest Zone (Southern Ghana):\n     - Wet Evergreen Forest (Rainforest): Southwestern corner (Ankasa Game Production Reserve); rainfall > 2,000 mm; nutrient-poor leached soils; highest biodiversity.\n     - Moist Evergreen: Surrounds the wet evergreen belt; rich in commercial timber species (Mahogany, Sapele).\n     - Moist Semi-Deciduous Forest: Central agricultural belt (Ashanti, Eastern, Bono regions); rainfall 1,200–1,600 mm; prime home of Odum, Wawa, and cocoa production. Trees shed leaves partially during dry season.\n     - Dry Semi-Deciduous: Boundary zone transitioning into northern savanna.\n  2. Savanna Woodlands: Covers > 50% of Ghana (Northern, Upper East, Upper West, Savannah regions); tall grasses and fire-resistant drought-tolerant deciduous trees (Shea, Baobab, Dawadawa).\n  3. Coastal Mangrove Forests: Salt-tolerant stilt-rooted trees (Rhizophora) fringing coastal lagoons and river estuaries (Volta estuary, Keta lagoon).\n• Tropical Rainforest Canopy Stratification:\n  - Emergent Layer: Giant trees towering 40–60 meters high with broad buttress roots.\n  - Canopy Layer: Dense continuous roof of interlocking tree crowns (20–40 m); absorbs 90% of sunlight.\n  - Understory Layer: Shorter trees, palms, lianas, and shade-tolerant saplings (5–20 m).\n  - Forest Floor: Decomposing leaf litter, fungal mycelia, seedlings; virtually dark.",
