    "description": "Measuring Diameter at Breast Height (DBH: 1.3m) with calipers/diameter tape, measuring tree height (clinometer, hypsometer), log volume (Huber's and Smalian's formulas).",
    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Forest Mensuration Defined: The determination of dimensions, form, volume, age, and increment of standing trees, logs, and whole forest stands.\n• Measuring Diameter at Breast Height (DBH):\n  - Standard Height: Measured at exactly 1.30 meters (4.3 feet) above the ground on the uphill side of the tree trunk.\n  - Above buttresses: If tree has large buttresses exceeding 1.3 m, DBH is measured 30–50 cm above the buttress swell.\n  - Instruments: Tree Calipers (for circular trunks) and Diameter Tape (graduated in units of pi, converting circumference directly into diameter!).\n• Measuring Tree Height:\n  - Instruments: Suunto Clinometer, Haga Altimeter, Blume-Leiss Hypsometer. Operates on trigonometric principles: Height = Distance * tan(Angle) + Observer Eye Height.\n• Calculating Log Volume:\n  - Smalian's Formula: Volume = [(Cross-section Area of Base + Cross-section Area of Top) / 2] * Log Length.\n  - Huber's Formula: Volume = Cross-section Area at Midpoint * Log Length.",
