    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Timber Harvesting (Logging Operations):\n  1. Tree Selection & Inspection: Checking minimum felling diameter limits (e.g. 70–110 cm DBH depending on species).\n  2. Directional Felling: Making a directional notch / undercut on the fall side and a felling back-cut slightly above to direct the fall safely, preventing damage to neighboring trees.\n  3. De-limbing and Bucking: Cutting the felled trunk into merchantable log lengths with chainsaws.\n  4. Skidding / Yarding: Dragging logs from stump to forest loading bay (log landing) using heavy wheeled skidders or bulldozers.\n  5. Hauling: Transporting logs on articulated timber trucks to sawmills or ports.\n• Sawmill Processing & Conversion:\n  - Plain / Flat Sawing: Tangential cuts; fastest, least waste, but prone to warping and cupping.\n  - Quarter Sawing: Radial cuts toward center; dimensionally stable, beautiful ray fleck patterns, but more expensive and higher waste.\n• Wood Seasoning & Preservation:\n  - Seasoning: Drying wood to reduce moisture content from green state (> 50%) to 12–15% for indoor use (Air Seasoning vs. Kiln Seasoning). Prevents warping, cracking, and fungal rot.\n  - Preservation: Treating wood with chemical preservatives (Creosote, Copper Chrome Arsenate - CCA) in vacuum pressure cylinders.",
